import {readFileSync, writeFileSync, mkdirSync, rmSync} from 'node:fs';
import vm from 'node:vm';
import {fileURLToPath} from 'node:url';

// Keep the website as the content source; generated files never contain DOM code.
const root = new URL('../', import.meta.url);
const target = new URL('miniprogram/', root);
const context = vm.createContext({});
for (const name of ['guanyin', 'tarot', 'lore', 'yijing-data', 'liuyao', 'cookie']) {
  vm.runInContext(readFileSync(new URL(`${name}.js`, root), 'utf8'), context);
}
const app = readFileSync(new URL('app.js', root), 'utf8');
const extract = (start, end) => app.slice(app.indexOf(start), app.indexOf(end));
vm.runInContext(extract('const definitions=', 'const BUFF_COUNT='), context);
vm.runInContext(extract('function categoryArt(', 'function categoryImage('), context);
vm.runInContext(`
  function getLiuyao(){return null;}
  function getLore(id){return BUFF_LORE[id][0];}
  const currentDay='';
`, context);
const data = vm.runInContext(`({
  definitions, pools:{sign:GUANYIN_SIGNS,tarot:TAROT_CARDS,...BUFF_LORE,
  cookie:COOKIE_FORTUNES,liuyao:YIJING_HEXAGRAMS},
  trigrams:TRIGRAMS, kingWen:KING_WEN,
  icons:definitions.map(d=>categoryArt(d,false)),
  hexagrams:YIJING_HEXAGRAMS.map(h=>hexagramArtwork(h.number))
})`, context);
mkdirSync(new URL('data/', target), {recursive:true});
const assetDir = new URL('assets/generated/', target);
rmSync(assetDir, {recursive:true, force:true});
mkdirSync(assetDir, {recursive:true});
const asset = (filename, svg) => {
  if (/<style\b|(?:width|height)="[^"]*%"/i.test(svg)) throw new Error(`Unsupported SVG: ${filename}`);
  writeFileSync(new URL(filename, assetDir), svg);
  return `/assets/generated/${filename}`;
};
data.definitions.forEach((def, i) => {
  delete def.pool;
  delete def.symbol;
  def.image = asset(`${def.id}-icon.svg`, data.icons[i].svg);
  data.pools[def.id].forEach((item, index) => {
    item.image = item.svg ? asset(`${def.id}-${index}.svg`, item.svg) :
      def.id === 'liuyao' ? asset(`hexagram-${item.number}.svg`, data.hexagrams[index].svg) : def.image;
    delete item.svg;
  });
});
delete data.icons;
delete data.hexagrams;
writeFileSync(new URL('data/content.js', target), '// Generated by scripts/build-miniprogram-data.mjs. Edit the website content source.\nmodule.exports = ' + JSON.stringify(data) + ';\n');
console.log(`Mini Program content generated: ${fileURLToPath(target)}`);
